3	using eShop.Ordering.Domain.AggregatesModel.OrderAggregate;
4	
5	// Regular CommandHandler
6	public class CreateOrderCommandHandler
7	    : IRequestHandler<CreateOrderCommand, bool>
8	{
9	    private readonly IOrderRepository _orderRepository;
10	    private readonly IIdentityService _identityService;
11	    private readonly IMediator _mediator;
12	    private readonly IOrderingIntegrationEventService _orderingIntegrationEventService;
13	    private readonly ILogger<CreateOrderCommandHandler> _logger;
14	
15	    // Using DI to inject infrastructure persistence Repositories
16	    public CreateOrderCommandHandler(IMediator mediator,
17	        IOrderingIntegrationEventService orderingIntegrationEventService,
18	        IOrderRepository orderRepository,
19	        IIdentityService identityService,
20	        ILogger<CreateOrderCommandHandler> logger)
21	    {
22	        _orderRepository = orderRepository ?? throw new ArgumentNullException(nameof(orderRepository));
23	        _identityService = identityService ?? throw new ArgumentNullException(nameof(identityService));
24	        _mediator = mediator ?? throw new ArgumentNullException(nameof(mediator));
25	        _orderingIntegrationEventService = orderingIntegrationEventService ?? throw new ArgumentNullException(nameof(orderingIntegrationEventService));
26	        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
27	    }
28	
29	    public async Task<bool> Handle(CreateOrderCommand message, CancellationToken cancellationToken)
30	    {
31	        // Add Integration event to clean the basket
32	        var orderStartedIntegrationEvent = new OrderStartedIntegrationEvent(message.UserId);
33	        await _orderingIntegrationEventService.AddAndSaveEventAsync(orderStartedIntegrationEvent);
34	
35	        // Add/Update the Buyer AggregateRoot
36	        // DDD patterns comment: Add child entities and value-objects through the Order Aggregate-Root
37	        // methods and constructor so validations, invariants and business logic 
38	        // make sure that consistency is preserved across the whole aggregate
39	        var address = new Address(message.Street, message.City, message.State, message.Country, message.ZipCode);
40	        var order = new Order(message.UserId, message.UserName, address, message.CardTypeId, message.CardNumber, message.CardSecurityNumber, message.CardHolderName, message.CardExpiration);
41	
